"""Rebuild D5 fixtures with the shared shell and component contract."""
from pathlib import Path
root=Path(__file__).resolve().parent
ns={'__file__':str(root/'build-mockups.py')}
exec((root/'build-mockups.py').read_text().split('eventrows=')[0],ns)
globals().update({k:v for k,v in ns.items() if k in ['shell','button','field','dialog','table','title','status','block']})
ns['nav'] += [('speakers-v03','Speakers','users'),('design-requests-v03','Design','calendar')]
# Existing icon dictionary uses the names below.
ns['nav'][-2]=('speakers-v03','Speakers','home')
def field(label,control):
 import html,re
 control=re.sub(r'<(input|select|textarea)\b',lambda m:m.group(0)+' aria-label="'+html.escape(label,quote=True)+'"',control,count=1)
 return '<label class="field"><span class="field-label">'+label+'</span>'+control+'</label>'
def inp(v='',typ='text'):return f'<input class="input" type="{typ}" value="{v}">'
def select(items):return '<select class="select">'+''.join(f'<option>{x}</option>' for x in items)+'</select>'
def form(fields,action):return '<form class="stack" data-preview-form>'+''.join(field(k,v) for k,v in fields)+button(action,True)+'</form>'
preview='<section class="section stack"><h2>Preview controls</h2><div class="action-row">'+field('Your role',select(['Officer','Director','Leadership','Owner']))+field('Data state',select(['Ready','Empty','Loading','Error']))+'</div><p class="small muted" id="permissions"></p></section>'
states='''<section id="empty" class="state state--brand" hidden><h2 class="state-title">Make room for what’s next.</h2><p class="state-body">STARTCOPY</p>STARTBUTTON</section><section id="loading" class="state state--loading" aria-busy="true" hidden><h2 class="state-title">Loading LABEL…</h2><div class="skel skel--row"></div><p role="status">Fetching the latest shared records.</p></section><section id="error" class="state state--error" hidden><h2 class="state-title">We couldn’t load LABEL</h2><p class="state-body">Your connection was interrupted. Your unsaved draft is still here.</p><button class="btn" data-retry>Try again</button></section>'''
js='''<script>
const searchInput=document.querySelector('input[placeholder="Name, organization or topic"]');if(searchInput)searchInput.oninput=()=>document.querySelectorAll('#ready tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(searchInput.value.toLowerCase()));
const selects=document.querySelectorAll('.section select');
function role(){const r=selects[0].value;document.documentElement.dataset.role=r.toLowerCase();document.querySelector('.user-chip-role').textContent=r;document.getElementById('permissions').textContent=r+' preview · '+(document.title.startsWith('Speakers')?'All officers, directors, leadership and owners can edit contacts and log outreach.':'Everyone sees this board and can request design. Designers self-assign and move work; only the requester approves in review. Rank grants no approval shortcut.');}role();selects[0].onchange=role;
selects[1].onchange=()=>{const s=selects[1].value.toLowerCase();['ready','empty','loading','error'].forEach(id=>document.getElementById(id).hidden=id!==s)};
document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{selects[1].value='Ready';selects[1].onchange()});
document.querySelectorAll('[data-preview-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();f.closest('dialog').close();document.getElementById('result').textContent='Saved in this visual prototype. Live data is unchanged.'});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('board').hidden=b.dataset.view!=='board';document.getElementById('request-list').hidden=b.dataset.view!=='list'});
const actor=document.getElementById('actor');if(actor)actor.onchange=()=>{document.querySelector('[data-approve]').disabled=actor.selectedIndex!==0};
document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>{b.textContent='Approved ✓';b.disabled=true;document.getElementById('approval').textContent='Maya approved this version. Jordan can now deliver the final files.'});
</script>'''
def write(key,heading,sub,body,dialogs,copy,cta):
 s=shell(key,heading,sub,preview+'<p id="result" role="status"></p><div id="ready" class="stack">'+body+'</div>'+states.replace('LABEL',heading.lower()).replace('STARTCOPY',copy).replace('STARTBUTTON',cta),dialogs)
 import re
 s=re.sub(r'(<td[^>]*>)(.*?)(</td>)',r'\1<div class="list-main">\2</div>\3',s)
 s=s.replace('document.getElementById(e.dataset.open).showModal()', '(()=>{document.querySelectorAll("dialog[open]").forEach(d=>d.close());document.getElementById(e.dataset.open).showModal()})()')
 s=s.replace('</head>','<link rel="stylesheet" href="../v03.css"></head>').replace('</body>',js+'</body>')
 (root/'mockups'/f'{key}.html').write_text(s)
contacts=[('Priya Shah','North Shore Ventures · Partner','Both','Fundraising · Early-stage ventures','priya@northshore.example','priya-shah','Founder stories: building from zero','Maya Patel · Oct 30, 2026','Email · Interested; follow up Nov 5'),('Daniel Kim','Fable Studio · Product designer','Speaker','Product design · Accessibility','daniel@fable.example','daniel-kim','Design for people','Jordan Lee · Oct 25, 2026','LinkedIn · Confirmed for spring'),('Sofia Nguyen','UBC Venture Lab · Mentor','Mentor','Customer discovery · Climate tech','sofia@venture.example','sofia-nguyen','No past events yet','Alex Chen · Oct 29, 2026','Email · Awaiting reply')]
rows=[]
for n,org,t,topics,email,li,event,who,outcome in contacts:
 rows.append([title(n,org)+(button('View contact',False,'data-open="contact"') if n=='Priya Shah' else button('View contact',False,'data-open="contact-'+li+'"')),status(t)+f'<span class="cell-sub">{topics}</span>',f'<a href="mailto:{email}">{email}</a><span class="cell-sub"><a href="https://www.linkedin.com/in/{li}/">LinkedIn ↗</a></span>',('Has done an event with us<br><a href="events.html">'+event+'</a>') if event!='No past events yet' else event,title(who,outcome)])
contact_fields=[('Name',inp('Priya Shah')),('Organization',inp('North Shore Ventures')),('Role',inp('Partner')),('Type',select(['Both','Speaker','Mentor'])),('Topics',inp('Fundraising, Early-stage ventures')),('Email',inp('priya@northshore.example','email')),('LinkedIn',inp('https://www.linkedin.com/in/priya-shah/','url')),('General notes','<textarea class="textarea">Prefers a small founder Q&A over a lecture. Available weekday evenings; send an outline two weeks ahead.</textarea>')]
extra_contacts=''.join(dialog('contact-'+li,n,form([('Name',inp(n)),('Organization / role',inp(org)),('Type',select([t,'Speaker','Mentor','Both'])),('Topics',inp(topics)),('Email',inp(email,'email')),('LinkedIn',inp('https://www.linkedin.com/in/'+li+'/','url')),('General notes','<textarea class="textarea">Follow up about next term’s program.</textarea>')],'Save contact')+'<h2>Outreach log</h2><p>'+who+' · '+outcome+'</p>'+button('Log outreach',False,'data-open="outreach"')) for n,org,t,topics,email,li,event,who,outcome in contacts[1:])
contact_detail='<p class="small muted">SAMPLE CONTACT · All officers can edit</p>'+form(contact_fields,'Save contact')+'<h2>Past events</h2><p>Has done an event with us: <a href="events.html">Founder stories: building from zero · Oct 28, 2026</a></p><h2>Outreach log</h2><ol class="timeline"><li><strong>Maya Patel · Oct 30, 2026, 2:15 PM</strong><p>Email · Interested</p><p>Happy to return for a founder Q&A. Follow up Nov 5 with the proposed date.</p></li><li><strong>Alex Chen · Oct 12, 2026, 10:30 AM</strong><p>LinkedIn · Confirmed</p><p>Confirmed Oct 28 and shared the speaker outline.</p></li></ol>'+button('Log outreach',True,'data-open="outreach"')
outreach=form([('Contact',select(['Priya Shah','Daniel Kim','Sofia Nguyen'])),('Reached out by',inp('Maya Patel (you)')),('When',inp('2026-11-01T14:30','datetime-local')),('Channel',select(['Email','LinkedIn','Discord','Phone','In person'])),('Outcome',select(['Awaiting reply','Interested','Confirmed','Declined','Follow up'])),('Notes','<textarea class="textarea" required placeholder="What happened, and what comes next?"></textarea>')],'Save outreach')+'<p class="small muted">Latest dated entry updates “Last reached out by”. Contact notes stay separate.</p>'
write('speakers-v03','Speakers & Mentors','People who share what they know. Keep the next conversation in context.','<div class="toolbar">'+field('Find a contact','<input class="input" placeholder="Name, organization or topic">')+button('Add contact',True,'data-open="add-contact"')+'</div>'+table(['Contact','Type & topics','Reach them','Past events','Last reached out by'],rows,caption='Speaker and mentor directory')+'<p class="small muted">3 contacts · Illustrative CSEED data · Contact addresses use reserved example domains.</p>',extra_contacts+dialog('contact','Priya Shah',contact_detail,True)+dialog('add-contact','Add contact',form([(k,inp() if k!='Type' else select(['Speaker','Mentor','Both'])) for k,v in contact_fields],'Add contact'))+dialog('outreach','Log outreach',outreach),'Start a shared directory so the next officer has the context.',button('Add your first contact',True,'data-open="add-contact"'))
requests=[('new','New','Venture night poster','Poster','Nov 6 · High urgency','Unassigned','Fall venture night','A3 print · PDF'),('accepted','Accepted','Mentor coffee social','Social','Nov 9 · Normal','Jordan Lee','Coffee & cofounders','1080 × 1350 · PNG'),('in-progress','In progress','Pitch clinic slides','Slides','Nov 5 · Due soon','Riley Park','Pitch clinic','16:9 · PPTX + PDF'),('in-review','In review','Founder stories cover','Social','Nov 4 · Due soon','Jordan Lee','Founder stories II','1600 × 900 · PNG'),('delivered','Delivered','Fall team shirt','Merch','Oct 30 · Delivered','Riley Park','Officer program','Vector · SVG + PDF')]
board='<div id="board" class="kanban" role="region" tabindex="0" aria-label="Design request board">'
for stage,label,name,typ,due,person,event,size in requests:
 board+=f'<section class="kanban-col" data-stage="{stage}"><div class="kanban-col-head"><h3 class="kanban-col-name">{label}</h3><span class="kanban-count">1</span></div><ul class="kanban-list"><li class="kanban-card"><a class="kanban-card-title" href="#detail-{stage}" data-open="detail-{stage}">{name}</a><div class="kanban-card-meta"><span class="kanban-tag" data-hue="blue">{typ}</span><span class="kanban-due">{due}</span></div><a class="kanban-link" href="events.html">{event} ↗</a><p class="small muted">{size}</p><div class="kanban-card-foot"><span class="kanban-unassigned">{person}</span><button class="icon-btn" aria-label="Actions for {name}" data-open="move">⋯</button></div></li></ul></section>'
board=board.replace('data-open="detail-in-review"','data-open="request-detail"')
board+='</div>'
reqform=form([('Title',inp('Venture night poster')),('Type',select(['Poster','Social','Slides','Merch','Other'])),('Linked event or program',select(['Fall venture night','Founder stories II','Officer program'])),('Due date',inp('2026-11-06','date')),('Urgency',select(['Normal','High · date cannot move'])),('Sizes / formats',inp('A3 print PDF; 1080 × 1350 PNG')),('Brief','<textarea class="textarea" required>Invite student founders to share a 3-minute pitch. Lead with Nov 12, 6 PM, The Nest. Include the RSVP QR code.</textarea>'),('References','<textarea class="textarea">Use the approved CSEED wordmark and fall event template. Keep room for sponsor marks.</textarea>'),('Attachments','<input class="input" type="file" multiple><span class="field-hint">Poster copy, logo assets and QR code · PDF, PNG, SVG</span>')],'Submit design request')
detail=status('In review')+'<p>Requested by Maya Patel · Assigned to Jordan Lee</p><dl class="facts"><div><dt>Type</dt><dd>Social</dd></div><div><dt>Due / urgency</dt><dd>Nov 4, 2026 · Normal</dd></div><div><dt>Event</dt><dd><a href="events.html">Founder stories II</a></dd></div><div><dt>Formats</dt><dd>1600 × 900 PNG; editable SVG</dd></div></dl><h2>Brief</h2><p>A Luma cover for the next founder Q&A. Include the event title, Nov 6 at 6 PM, and CSEED wordmark.</p><h2>References & attachments</h2><p>Approved fall template · <a href="../img/">Brand reference images</a></p><h2>Review files</h2><p class="file-name">founder-stories-cover-v2.png <span class="file-meta">Preview file · 240 KB</span></p><p id="approval" class="notice notice--info">Waiting for Maya, the requester, to approve this version.</p>'+field('Acting as', '<select class="select" id="actor"><option>Requester · Maya Patel</option><option>Designer · Jordan Lee</option><option>Other officer · Alex Chen</option></select>')+button('Approve this version',True,'data-approve')+'<p class="small muted" id="actor-hint">Approval is available only to the requester while In review.</p><h2>Comments</h2><ol class="timeline"><li><strong>Maya · Nov 1, 10:12 AM</strong><p>Could the date be larger on mobile?</p></li><li><strong>Jordan · Nov 1, 11:05 AM</strong><p>Updated in v2. Ready for your review.</p></li></ol>'+form([('Add a comment','<textarea class="textarea" required></textarea>')],'Post comment')+'<h2>Delivered files · completed example</h2><p class="small muted">Fall team shirt · delivered Oct 30 by Riley</p><p class="file-name">cseed-team-shirt.svg · Editable vector</p><p class="file-name">cseed-team-shirt-print.pdf · Print ready</p>'
extra_requests=''.join(dialog('detail-'+r[0],r[2],status(r[1])+'<p>Requested by Maya Patel</p><dl class="facts"><div><dt>Designer</dt><dd>'+r[5]+'</dd></div><div><dt>Due / urgency</dt><dd>'+r[4]+'</dd></div><div><dt>Type / formats</dt><dd>'+r[3]+' · '+r[7]+'</dd></div></dl><p><a href="events.html">'+r[6]+'</a></p><h2>Brief</h2><p>Create the '+r[3].lower()+' assets for '+r[6]+'. Use approved CSEED identity and make the date readable on mobile.</p><h2>Comments</h2><p>Maya · Nov 1: Please use the fall program template.</p>'+form([('Add a comment','<textarea class="textarea" required></textarea>')],'Post comment')+(('<h2>Delivered files</h2><p class="file-name">cseed-team-shirt.svg · Editable vector</p><p class="file-name">cseed-team-shirt-print.pdf · Print ready</p>') if r[0]=='delivered' else button('Designer actions',False,'data-open="move"'))) for r in requests if r[0]!='in-review')
move=form([('Assignee',select(['Unassigned','Jordan Lee (self-assign)','Riley Park'])),('Move to',select(['New','Accepted','In progress','In review','Delivered']))],'Update request')+'<p class="small muted">Designers self-assign and move work. Delivery follows requester approval. Use this menu with keyboard or touch; dragging is optional.</p>'
body='<div class="toolbar">'+button('New design request',True,'data-open="new-design"')+'<div class="segmented" role="group" aria-label="Board view"><button class="segment" aria-pressed="true" data-view="board">Board</button><button class="segment" aria-pressed="false" data-view="list">List</button></div></div><p class="small muted">5 requests · Shared with everyone · Deadlines shown in Vancouver time</p>'+board+'<div id="request-list" hidden>'+table(['Request','Stage','Due','Designer','Sizes / formats'],[[title(r[2],r[3])+button('Open request',False,'data-open="'+('request-detail' if r[0]=='in-review' else 'detail-'+r[0])+'"'),r[1],r[4],r[5],r[7]] for r in requests],caption='Design requests list')+'</div>'
write('design-requests-v03','Design requests','From a clear brief to something ready to share.',body,extra_requests+dialog('new-design','New design request',reqform,True)+dialog('request-detail','Founder stories cover',detail,True)+dialog('move','Designer actions',move),'Your next event deserves a good first impression. Give the design team a clear brief.',button('New design request',True,'data-open="new-design"'))
